import React, { useEffect, useState } from 'react';
import NavBar from '../Components/NavBar';
import '.announcement'

export default function Announcements() {
  const [ads, setAds] = useState([]);

  useEffect(() => {
    const fetchAds = async () => {
      try {
        const response = await fetch('http://localhost:5000/advertisements');
        if (response.ok) {
          const data = await response.json();
          setAds(data);
        }
      } catch (error) {
        console.error('Failed to fetch advertisements:', error);
      }
    };
    fetchAds();
  }, []);

  return (
    <div>
      <NavBar />
      <div style={{ padding: '20px' }}>
        <h2>Advertisements</h2>
        {ads.length === 0 && <p>No advertisements to show.</p>}
        {ads.map(ad => (
          <div key={ad.id} style={{
            border: '1px solid #ddd',
            padding: '15px',
            marginBottom: '15px',
            borderRadius: '6px',
            boxShadow: '0 2px 5px rgba(0,0,0,0.1)'
          }}>
            <h3>{ad.title}</h3>
            <p>{ad.content}</p>
            {ad.link && <a href={ad.link} target="_blank" rel="noopener noreferrer">Learn more</a>}
          </div>
        ))}
      </div>
    </div>
  );
}
